pub fn is_non_prime(n: u64) -> bool {
    // By assumption, n >= 2.
    // 2 and 3 are prime, so they are not "non-prime".
    if n <= 3 {
        return false;
    }
    // Even numbers greater than 2 are composite.
    if n % 2 == 0 {
        return true;
    }
    // Only need to test odd divisors up to sqrt(n).
    let limit = (n as f64).sqrt() as u64;
    let mut k = 3;
    while k <= limit {
        if n % k == 0 {
            return true;
        }
        k += 2;
    }
    false
}